//! Stadium names that the save does not store.
//!
//! A save keeps a name inline on only a couple of hundred grounds. The game
//! renders every other ground's name from its installed database, so
//! `shared/stadium-names.csv` holds the database's stadium table (`uid,name`).
//! The table is generated by `scripts/build_stadium_names.py` from the
//! installed FM27 2700 database and can be regenerated for another database.
//!
//! A save also stores object references that name a ground even when the save
//! row's uid differs from the database uid. The reference record is:
//!
//! `02 | u32 stadium ordinal + 1 | u32 database uid | u32 name length | name`
//!
//! It appears in `news`, `play_fixture_manager` and `edit_session_man`. A
//! reference is accepted only when its name matches the database name for that
//! uid after ignoring case and punctuation; that keeps unrelated records whose
//! first word happens to fall in the stadium range out of the table.

use std::collections::HashMap;
use std::sync::OnceLock;

use crate::container::SaveFile;
use crate::layout::read_u32;

/// Sections that can carry a named stadium reference.
const REFERENCE_SECTIONS: [&str; 3] = ["news", "play_fixture_manager", "edit_session_man"];
/// Byte that starts a named object reference.
const REFERENCE_TAG: u8 = 0x02;
/// The longest reference name read as a stadium name.
const MAX_REFERENCE_NAME_BYTES: usize = 128;
/// The largest stadium ordinal accepted from a reference record.
const MAX_STADIUM_ORDINAL: u32 = 1_000_000;

/// The database name for a stadium uid, when the bundled table has one.
pub fn name_for_uid(uid: u32) -> Option<&'static str> {
    names().get(&uid).map(String::as_str)
}

/// How many stadium names the bundled table holds.
pub fn name_count() -> usize {
    names().len()
}

/// Read the named-ground references in a save, keyed by the stadium row index
/// (zero based). Missing or unreadable sections are skipped.
pub fn read_name_references(save: &SaveFile) -> HashMap<usize, String> {
    let mut references = HashMap::new();
    for section in REFERENCE_SECTIONS {
        let Ok(bytes) = save.read_section(section) else {
            continue;
        };
        scan_name_references(&bytes, &mut references);
    }
    references
}

/// Scan one section for validated stadium references.
fn scan_name_references(bytes: &[u8], references: &mut HashMap<usize, String>) {
    for offset in memchr::memchr_iter(REFERENCE_TAG, bytes) {
        if offset + 13 > bytes.len() {
            break;
        }
        let Some(ordinal_plus_one) = read_u32(bytes, offset + 1) else {
            continue;
        };
        if !(2..=MAX_STADIUM_ORDINAL).contains(&ordinal_plus_one) {
            continue;
        }
        let Some(database_uid) = read_u32(bytes, offset + 5) else {
            continue;
        };
        let Some(length) = read_u32(bytes, offset + 9) else {
            continue;
        };
        let length = length as usize;
        if length == 0 || length > MAX_REFERENCE_NAME_BYTES {
            continue;
        }
        let start = offset + 13;
        let Some(name_bytes) = bytes.get(start..start.saturating_add(length)) else {
            continue;
        };
        let Ok(name) = std::str::from_utf8(name_bytes) else {
            continue;
        };
        let name = name.trim();
        if name.is_empty() || name.chars().any(char::is_control) {
            continue;
        }
        let Some(database_name) = name_for_uid(database_uid) else {
            continue;
        };
        if !names_match(database_name, name) {
            continue;
        }
        let row_index = (ordinal_plus_one - 2) as usize;
        references
            .entry(row_index)
            .or_insert_with(|| name.to_owned());
    }
}

/// Whether two stadium names are the same apart from case and punctuation.
fn names_match(left: &str, right: &str) -> bool {
    let left = normalized(left);
    let right = normalized(right);
    left.chars().count() >= 3 && left == right
}

fn normalized(text: &str) -> String {
    text.chars()
        .filter(|character| character.is_alphanumeric())
        .flat_map(|character| character.to_lowercase())
        .collect()
}

fn names() -> &'static HashMap<u32, String> {
    static NAMES: OnceLock<HashMap<u32, String>> = OnceLock::new();
    NAMES.get_or_init(|| {
        let mut map = HashMap::new();
        let mut reader = csv::ReaderBuilder::new()
            .has_headers(true)
            .from_reader(include_str!("../../../shared/stadium-names.csv").as_bytes());
        for row in reader.records().flatten() {
            let Some(uid) = row
                .get(0)
                .and_then(|value| value.trim().parse::<u32>().ok())
            else {
                continue;
            };
            let name = row.get(1).unwrap_or("").trim();
            if !name.is_empty() {
                map.insert(uid, name.to_owned());
            }
        }
        map
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn reference(ordinal_plus_one: u32, database_uid: u32, name: &str) -> Vec<u8> {
        let mut bytes = vec![REFERENCE_TAG];
        bytes.extend_from_slice(&ordinal_plus_one.to_le_bytes());
        bytes.extend_from_slice(&database_uid.to_le_bytes());
        bytes.extend_from_slice(&(name.len() as u32).to_le_bytes());
        bytes.extend_from_slice(name.as_bytes());
        bytes.extend_from_slice(&[0; 8]);
        bytes
    }

    #[test]
    fn bundled_table_has_known_stadiums() {
        assert!(name_count() > 30_000);
        assert_eq!(name_for_uid(680), Some("Old Trafford"));
        assert_eq!(name_for_uid(676), Some("Anfield"));
        assert_eq!(name_for_uid(5_114_336), Some("Emirates Stadium"));
        assert_eq!(name_for_uid(28_096_287), Some("Tottenham Hotspur Stadium"));
        assert_eq!(name_for_uid(29_128_182), Some("Gtech Community Stadium"));
    }

    #[test]
    fn names_match_across_case_and_punctuation() {
        assert!(names_match("Allianz Arena", "Allianz-Arena"));
        assert!(names_match("St. James' Park", "St James Park"));
        assert!(!names_match("Old Trafford", "First Leg"));
        assert!(!names_match("RSN", "RS"));
    }

    #[test]
    fn scan_accepts_a_reference_whose_uid_matches_the_row() {
        let mut references = HashMap::new();
        scan_name_references(&reference(71, 680, "Old Trafford"), &mut references);
        assert_eq!(
            references.get(&69).map(String::as_str),
            Some("Old Trafford")
        );
    }

    #[test]
    fn scan_bridges_a_dynamic_uid_to_the_database_uid() {
        let mut references = HashMap::new();
        scan_name_references(&reference(1976, 156_312, "San Siro"), &mut references);
        assert_eq!(references.get(&1974).map(String::as_str), Some("San Siro"));

        let mut references = HashMap::new();
        scan_name_references(
            &reference(8458, 8_700_726, "Allianz Arena"),
            &mut references,
        );
        assert_eq!(
            references.get(&8456).map(String::as_str),
            Some("Allianz Arena")
        );
    }

    #[test]
    fn scan_rejects_a_name_that_does_not_match_the_database() {
        let mut references = HashMap::new();
        scan_name_references(&reference(71, 680, "First Leg"), &mut references);
        assert!(references.is_empty());
    }
}
